// SetAttachedPost of the post to the related item.
// Sets o.R.AttachedPost to related.
// Adds o to related.R.AttachedPostPosts.
func (o *Post) SetAttachedPost(ctx context.Context, exec boil.ContextExecutor, insert bool, related *Post) error {
	var err error
	if insert {
		if err = related.Insert(ctx, exec, boil.Infer()); err != nil {
			return errors.Wrap(err, "failed to insert into foreign table")
		}
	}

	updateQuery := fmt.Sprintf(
		"UPDATE \"posts\" SET %s WHERE %s",
		strmangle.SetParamNames("\"", "\"", 1, []string{"attached_post_id"}),
		strmangle.WhereClause("\"", "\"", 2, postPrimaryKeyColumns),
	)
	values := []any{related.ID, o.ID}

	if boil.IsDebug(ctx) {
		writer := boil.DebugWriterFrom(ctx)
		fmt.Fprintln(writer, updateQuery)
		fmt.Fprintln(writer, values)
	}
	if _, err = exec.ExecContext(ctx, updateQuery, values...); err != nil {
		return errors.Wrap(err, "failed to update local table")
	}

	queries.Assign(&o.AttachedPostID, related.ID)
	if o.R == nil {
		o.R = &postR{
			AttachedPost: related,
		}
	} else {
		o.R.AttachedPost = related
	}

	if related.R == nil {
		related.R = &postR{
			AttachedPostPosts: PostSlice{o},
		}
	} else {
		related.R.AttachedPostPosts = append(related.R.AttachedPostPosts, o)
	}

	return nil
}

// RemoveAttachedPost relationship.
// Sets o.R.AttachedPost to nil.
// Removes o from all passed in related items' relationships struct.
func (o *Post) RemoveAttachedPost(ctx context.Context, exec boil.ContextExecutor, related *Post) error {
	var err error

	queries.SetScanner(&o.AttachedPostID, nil)
	if _, err = o.Update(ctx, exec, boil.Whitelist("attached_post_id")); err != nil {
		return errors.Wrap(err, "failed to update local table")
	}

	if o.R != nil {
		o.R.AttachedPost = nil
	}
	if related == nil || related.R == nil {
		return nil
	}

	for i, ri := range related.R.AttachedPostPosts {
		if queries.Equal(o.AttachedPostID, ri.AttachedPostID) {
			continue
		}

		ln := len(related.R.AttachedPostPosts)
		if ln > 1 && i < ln-1 {
			related.R.AttachedPostPosts[i] = related.R.AttachedPostPosts[ln-1]
		}
		related.R.AttachedPostPosts = related.R.AttachedPostPosts[:ln-1]
		break
	}
	return nil
}

